1	import { useState, useEffect, useCallback } from "react";
2	import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
3	import { useLoaderData, useFetcher, useNavigate } from "react-router";
4	import { useAppBridge } from "@shopify/app-bridge-react";
5	import { authenticate } from "../shopify.server";
6	import db from "../db.server";
7	import { PLANS, getPlan } from "../lib/plans";
8	import { createSubscription, cancelSubscription } from "../lib/billing.server";
9	import type { Plan } from "../lib/plans";
10	import {
11	  Page,
12	  Layout,
13	  Card,
14	  BlockStack,
15	  InlineStack,
16	  Text,
17	  Badge,
18	  Button,
19	  ButtonGroup,
20	  Divider,
21	  Box,
22	  Banner,
23	  Icon,
24	  Modal,
25	  InlineGrid,
26	} from "@shopify/polaris";
27	import { CheckCircleIcon, XCircleIcon, StarIcon } from "@shopify/polaris-icons";
28	
29	// ─── Plan display data ──────────────────────────────────────────────────────
30	
31	const PLAN_ORDER = ["free", "starter", "growth", "pro"] as const;
32	
33	const PLAN_DESCRIPTIONS: Record<string, string> = {
34	  free: "Get started — no credit card required",
35	  starter: "Essential tools for growing stores",
36	  growth: "AI-powered sizing for serious brands",
37	  pro: "Enterprise-grade power and control",
38	};
39	
40	// ─── Feature rows for comparison table ──────────────────────────────────────
41	
42	const FEATURE_ROWS: { label: string; key: keyof Plan["limits"] }[] = [
43	  { label: "Published size charts", key: "maxCharts" },
44	  { label: "CSV import / export", key: "csvImport" },
45	  { label: "Auto-assignment rules", key: "autoAssign" },
46	  { label: "Image support in charts", key: "imageInCharts" },
47	  { label: "Translate & Adapt (i18n)", key: "translateAdapt" },
48	  { label: "Analytics dashboard", key: "analytics" },
49	  { label: "Dedicated sizing page", key: "dedicatedSizingPage" },
50	  { label: "AI size recommender", key: "aiRecommender" },
51	  { label: "Advanced ML recommender", key: "advancedAi" },
52	  { label: "Return attribution", key: "returnAttribution" },
53	  { label: "Priority support (<2hr)", key: "prioritySupport" },
54	  { label: "Multi-store sync", key: "multiStore" },
55	];
56	
57	// ─── Loader ─────────────────────────────────────────────────────────────────
58	
59	export const loader = async ({ request }: LoaderFunctionArgs) => {
60	  const { session } = await authenticate.admin(request);
61	  const subscription = await db.subscription.findUnique({
62	    where: { shop: session.shop },
63	  });
64	  return {
65	    currentPlan: getPlan(subscription?.planId ?? "free"),
66	    billingInterval: subscription?.billingInterval ?? "monthly",
67	    plans: PLANS,
68	  };
69	};
70	
71	// ─── Action ─────────────────────────────────────────────────────────────────
72	
73	export const action = async ({ request }: ActionFunctionArgs) => {
74	  const { session, admin } = await authenticate.admin(request);
75	  const shop = session.shop;
76	  const formData = await request.formData();
77	  const intent = formData.get("intent") as string;
78	
79	  const billingContext = { admin, session: { shop } };
80	
81	  try {
82	    if (intent === "subscribe") {
83	      const planId = formData.get("planId") as string;
84	      const interval = (formData.get("interval") as string) || "monthly";
85	      const plan = getPlan(planId);
86	
87	      if (plan.price === 0) {
88	        // Downgrade to free — cancel existing Shopify subscription if any
89	        try {
90	          await cancelSubscription(billingContext);
91	        } catch {
92	          // No active subscription to cancel — that's fine
93	        }
94	        await db.subscription.upsert({
95	          where: { shop },
96	          update: { planId: "free", status: "active", billingInterval: "monthly", shopifySubscriptionId: null },
97	          create: { shop, planId: "free", billingInterval: "monthly", status: "active" },
98	        });
99	        return { ok: true, message: "Switched to Free plan" };
100	      }
101	
102	      // Create Shopify subscription — returns a confirmation URL
103	      const billingInterval = interval === "annual" ? "annual" as const : "monthly" as const;
104	      const { confirmationUrl } = await createSubscription(
105	        billingContext,
106	        planId,
107	        billingInterval,
108	      );
109	
110	      // Redirect merchant to Shopify's hosted billing approval page
111	      return { ok: true, message: `Redirecting to billing approval...`, confirmationUrl };
112	    }
113	
114	    if (intent === "cancel") {
115	      await cancelSubscription(billingContext);
116	      return { ok: true, message: "Subscription cancelled. You are now on the Free plan." };
117	    }
118	
119	    return { error: "Unknown action" };
120	  } catch (error) {
121	    return { error: error instanceof Error ? error.message : "An unexpected error occurred" };
122	  }
123	};
124	
125	// ─── Feature row ────────────────────────────────────────────────────────────
126	
127	function PlanFeature({ feature }: { feature: string }) {
128	  return (
129	    <InlineStack gap="200" blockAlign="start" wrap={false}>
130	      <Box>
131	        <Icon source={CheckCircleIcon} tone="success" />
132	      </Box>
133	      <Text as="span" variant="bodyMd">
134	        {feature}
135	      </Text>
136	    </InlineStack>
137	  );
138	}
139	
140	// ─── Plan card ──────────────────────────────────────────────────────────────
141	
142	interface PlanCardProps {
143	  plan: Plan;
144	  isAnnual: boolean;
145	  currentTier: string;
146	  onSubscribe: (planId: string) => void;
147	  onRequestCancel: () => void;
148	  isLoading: boolean;
149	}
150	
151	function PlanCard({
152	  plan,
153	  isAnnual,
154	  currentTier,
155	  onSubscribe,
156	  onRequestCancel,
157	  isLoading,
158	}: PlanCardProps) {
159	  const isCurrent = currentTier === plan.id;
160	  const isMostPopular = plan.id === "growth";
161	  const tierIndex = PLAN_ORDER.indexOf(plan.id as (typeof PLAN_ORDER)[number]);
162	  const currentIndex = PLAN_ORDER.indexOf(currentTier as (typeof PLAN_ORDER)[number]);
163	  const isUpgrade = tierIndex > currentIndex;
164	  const isDowngrade = tierIndex < currentIndex;
165	
166	  const displayPrice = isAnnual
167	    ? (plan.annualPrice / 12).toFixed(2)
168	    : plan.price.toFixed(2);
169	
170	  let buttonContent = "Start free trial";
171	  let buttonVariant: "primary" | "secondary" | undefined = "primary";
172	  let buttonTone: "critical" | undefined = undefined;
173	
174	  if (isCurrent) {
175	    buttonContent = "Current plan";
176	    buttonVariant = "secondary";
177	  } else if (plan.price === 0) {
178	    buttonContent = "Downgrade to Free";
179	    buttonVariant = undefined;
180	    buttonTone = "critical";
181	  } else if (isUpgrade) {
182	    buttonContent = `Upgrade to ${plan.name}`;
183	  } else if (isDowngrade) {
184	    buttonContent = `Switch to ${plan.name}`;
185	  }
186	
187	  const handleClick = () => {
188	    if (isCurrent) return;
189	    if (plan.price === 0) {
190	      onRequestCancel();
191	    } else {
192	      onSubscribe(plan.id);
193	    }
194	  };
195	
196	  return (
197	    <Card>
198	      <BlockStack gap="400">
199	        {/* Plan name + badges */}
200	        <BlockStack gap="100">
201	          <InlineStack align="space-between" blockAlign="center">
202	            <Text as="h3" variant="headingMd" fontWeight="bold">
203	              {plan.name}
204	            </Text>
205	            <InlineStack gap="150">
206	              {isMostPopular && !isCurrent && (
207	                <Badge tone="info" icon={StarIcon}>
208	                  Most popular
209	                </Badge>
210	              )}
211	              {isCurrent && <Badge tone="success">Active</Badge>}
212	            </InlineStack>
213	          </InlineStack>
214	          <Text as="p" variant="bodySm" tone="subdued">
215	            {PLAN_DESCRIPTIONS[plan.id] ?? ""}
216	          </Text>
217	        </BlockStack>
218	
219	        <Divider />
220	
221	        {/* Price */}
222	        <BlockStack gap="100">
223	          {plan.price === 0 ? (
224	            <>
225	              <Text as="p" variant="headingXl" fontWeight="bold">
226	                Free
227	              </Text>
228	              <Text as="p" variant="bodySm" tone="subdued">
229	                forever — no credit card
230	              </Text>
231	            </>
232	          ) : (
233	            <>
234	              <InlineStack gap="100" blockAlign="baseline">
235	                <Text as="p" variant="headingXl" fontWeight="bold">
236	                  ${displayPrice}
237	                </Text>
238	                <Text as="p" variant="bodySm" tone="subdued">
239	                  / month
240	                </Text>
241	              </InlineStack>
242	              <Text as="p" variant="bodySm" tone="subdued">
243	                {isAnnual
244	                  ? `billed $${plan.annualPrice} / year`
245	                  : `or $${(plan.annualPrice / 12).toFixed(2)}/mo billed annually`}
246	              </Text>
247	            </>
248	          )}
249	        </BlockStack>
250	
251	        {/* CTA button */}
252	        <Button
253	          variant={buttonVariant}
254	          tone={buttonTone}
255	          onClick={handleClick}
256	          disabled={isCurrent}
257	          loading={isLoading && !isCurrent}
258	          fullWidth
259	        >
260	          {buttonContent}
261	        </Button>
262	
263	        <Divider />
264	
265	        {/* Features list */}
266	        <BlockStack gap="300">
267	          {plan.features.map((f) => (
268	            <PlanFeature key={f} feature={f} />
269	          ))}
270	        </BlockStack>
271	      </BlockStack>
272	    </Card>
273	  );
274	}
275	
276	// ─── Page ───────────────────────────────────────────────────────────────────
277	
278	export default function PricingPage() {
279	  const { currentPlan, billingInterval: initialInterval, plans } =
280	    useLoaderData<typeof loader>();
281	  const fetcher = useFetcher<typeof action>();
282	  const navigate = useNavigate();
283	  const shopify = useAppBridge();
284	
285	  const [isAnnual, setIsAnnual] = useState(initialInterval === "annual");
286	  const [cancelModalOpen, setCancelModalOpen] = useState(false);
287	
288	  const isFetching = fetcher.state !== "idle";
289	
290	  useEffect(() => {
291	    const data = fetcher.data;
292	    if (data && "ok" in data && data.ok) {
293	      // If Shopify returned a confirmation URL, redirect merchant to approve billing
294	      if ("confirmationUrl" in data && typeof data.confirmationUrl === "string") {
295	        if (window.top) {
296	          window.top.location.href = data.confirmationUrl;
297	        } else {
298	          window.location.href = data.confirmationUrl;
299	        }
300	        return;
301	      }
302	      shopify.toast.show(data.message ?? "Plan updated");
303	    } else if (data && "error" in data) {
304	      shopify.toast.show(data.error ?? "Error", { isError: true });
305	    }
306	  }, [fetcher.data, shopify]);
307	
308	  const handleSubscribe = useCallback(
309	    (planId: string) => {
310	      fetcher.submit(
311	        { intent: "subscribe", planId, interval: isAnnual ? "annual" : "monthly" },
312	        { method: "post" },
313	      );
314	    },
315	    [fetcher, isAnnual],
316	  );
317	
318	  const handleConfirmCancel = useCallback(() => {
319	    setCancelModalOpen(false);
320	    fetcher.submit({ intent: "cancel" }, { method: "post" });
321	  }, [fetcher]);
322	
323	  const orderedPlans = PLAN_ORDER.map((id) => plans.find((p) => p.id === id)).filter(
324	    (p): p is Plan => p !== undefined,
325	  );
326	
327	  // Next tier for upgrade banner
328	  const nextTier =
329	    currentPlan.id === "free"
330	      ? "starter"
331	      : currentPlan.id === "starter"
332	        ? "growth"
333	        : currentPlan.id === "growth"
334	          ? "pro"
335	          : null;
336	
337	  const actionError =
338	    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
339	
340	  return (
341	    <Page
342	      title="Plans & Pricing"
343	      subtitle="Simple, transparent pricing. No per-order fees ever."
344	      backAction={{ onAction: () => navigate("/app") }}
345	    >
346	      <Box paddingBlockEnd="1600">
347	        <Layout>
348	          {/* Error banner */}
349	          {actionError && (
350	            <Layout.Section>
351	              <Banner tone="critical" title="Billing error">
352	                <Text as="p" variant="bodyMd">
353	                  {actionError}
354	                </Text>
355	              </Banner>
356	            </Layout.Section>
357	          )}
358	
359	          <Layout.Section>
360	            <BlockStack gap="600">
361	              {/* Current plan status */}
362	              {nextTier ? (
363	                <Banner
364	                  tone="info"
365	                  title={`You're on the ${currentPlan.name} plan`}
366	                  action={{
367	                    content: `Upgrade to ${getPlan(nextTier).name}`,
368	                    onAction: () => handleSubscribe(nextTier),
369	                  }}
370	                >
371	                  <Text as="p" variant="bodyMd">
372	                    {currentPlan.id === "free"
373	                      ? "You have up to 3 published charts and basic widget access. Upgrade to unlock more."
374	                      : `Upgrade to ${getPlan(nextTier).name} for more features.`}
375	                  </Text>
376	                </Banner>
377	              ) : (
378	                <Banner tone="success" title={`You're on the ${currentPlan.name} plan`}>
379	                  <InlineStack gap="200" blockAlign="center">
380	                    <Badge tone="success">Active</Badge>
381	                    <Text as="p" variant="bodyMd">
382	                      You have full access to all features including advanced AI and priority support.
383	                    </Text>
384	                  </InlineStack>
385	                </Banner>
386	              )}
387	
388	              {/* Billing toggle */}
389	              <BlockStack gap="200" inlineAlign="center">
390	                <ButtonGroup variant="segmented">
391	                  <Button pressed={!isAnnual} onClick={() => setIsAnnual(false)}>
392	                    Monthly
393	                  </Button>
394	                  <Button pressed={isAnnual} onClick={() => setIsAnnual(true)}>
395	                    Annual · Save 20%
396	                  </Button>
397	                </ButtonGroup>
398	                {isAnnual && (
399	                  <Badge tone="success">You save up to 20% per year</Badge>
400	                )}
401	              </BlockStack>
402	
403	              {/* Plan cards — responsive 4-column grid */}
404	              <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
405	                {orderedPlans.map((plan) => (
406	                  <PlanCard
407	                    key={plan.id}
408	                    plan={plan}
409	                    isAnnual={isAnnual}
410	                    currentTier={currentPlan.id}
411	                    onSubscribe={handleSubscribe}
412	                    onRequestCancel={() => setCancelModalOpen(true)}
413	                    isLoading={isFetching}
414	                  />
415	                ))}
416	              </InlineGrid>
417	
418	              {/* Trial footnote */}
419	              {currentPlan.price === 0 && (
420	                <Text as="p" variant="bodySm" tone="subdued" alignment="center">
421	                  All paid plans include a 7-day free trial. No credit card charged until the trial ends.
422	                </Text>
423	              )}
424	
425	              {/* Guarantee */}
426	              <Banner tone="success" title="30-day money-back guarantee">
427	                <Text as="p" variant="bodyMd">
428	                  Not happy in the first 30 days? We&apos;ll refund you — no questions asked.
429	                  Cancel anytime directly from Shopify billing settings.
430	                </Text>
431	              </Banner>
432	
433	              {/* Why switch */}
434	              <BlockStack gap="400">
435	                <Text as="h2" variant="headingLg">
436	                  Why merchants switch to us
437	                </Text>
438	                <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
439	                  <Card>
440	                    <BlockStack gap="200">
441	                      <Text as="h3" variant="headingMd" fontWeight="bold">
442	                        No Per-Order Fees
443	                      </Text>
444	                      <Text as="p" variant="bodyMd" tone="subdued">
445	                        Competitors charge per order — costs balloon as your store grows.
446	                        We use simple flat monthly pricing. Your bill stays predictable.
447	                      </Text>
448	                    </BlockStack>
449	                  </Card>
450	                  <Card>
451	                    <BlockStack gap="200">
452	                      <Text as="h3" variant="headingMd" fontWeight="bold">
453	                        Mobile-First Widget
454	                      </Text>
455	                      <Text as="p" variant="bodyMd" tone="subdued">
456	                        iOS Safari bugs are the #1 complaint in competitor reviews.
457	                        Our widget is pixel-perfect on every device.
458	                      </Text>
459	                    </BlockStack>
460	                  </Card>
461	                  <Card>
462	                    <BlockStack gap="200">
463	                      <Text as="h3" variant="headingMd" fontWeight="bold">
464	                        Set Up in 5 Minutes
465	                      </Text>
466	                      <Text as="p" variant="bodyMd" tone="subdued">
467	                        Auto-detect product types, suggest templates, and auto-assign charts.
468	                        Most merchants publish their first chart in under 3 minutes.
469	                      </Text>
470	                    </BlockStack>
471	                  </Card>
472	                </InlineGrid>
473	              </BlockStack>
474	
475	              {/* Full Feature Comparison */}
476	              <BlockStack gap="400">
477	                <Text as="h2" variant="headingLg">
478	                  Full Feature Comparison
479	                </Text>
480	                <Card>
481	                  <BlockStack gap="0">
482	                    {/* Header row */}
483	                    <Box paddingBlockEnd="300">
484	                      <InlineStack align="space-between">
485	                        <Box minWidth="200px">
486	                          <Text as="p" variant="bodySm" tone="subdued">
487	                            Feature
488	                          </Text>
489	                        </Box>
490	                        {orderedPlans.map((plan) => (
491	                          <Box key={plan.id} minWidth="100px">
492	                            <BlockStack gap="100" inlineAlign="center">
493	                              <Text as="p" variant="headingSm" fontWeight="bold">
494	                                {plan.name}
495	                              </Text>
496	                              <Text as="p" variant="bodySm" tone="subdued">
497	                                {plan.price === 0
498	                                  ? "Free"
499	                                  : isAnnual
500	                                    ? `$${(plan.annualPrice / 12).toFixed(2)}/mo`
501	                                    : `$${plan.price}/mo`}
502	                              </Text>
503	                            </BlockStack>
504	                          </Box>
505	                        ))}
506	                      </InlineStack>
507	                    </Box>
508	
509	                    <Divider />
510	
511	                    {/* Feature rows */}
512	                    {FEATURE_ROWS.map((row) => (
513	                      <Box key={row.key} paddingBlock="300">
514	                        <InlineStack align="space-between" blockAlign="center">
515	                          <Box minWidth="200px">
516	                            <Text as="p" variant="bodyMd">
517	                              {row.label}
518	                            </Text>
519	                          </Box>
520	                          {orderedPlans.map((plan) => {
521	                            const val = plan.limits[row.key];
522	                            if (row.key === "maxCharts") {
523	                              return (
524	                                <Box key={plan.id} minWidth="100px">
525	                                  <InlineStack align="center">
526	                                    <Text as="p" variant="bodyMd" fontWeight="semibold">
527	                                      {val === -1 ? "Unlimited" : String(val)}
528	                                    </Text>
529	                                  </InlineStack>
530	                                </Box>
531	                              );
532	                            }
533	                            return (
534	                              <Box key={plan.id} minWidth="100px">
535	                                <InlineStack align="center">
536	                                  <Icon
537	                                    source={val ? CheckCircleIcon : XCircleIcon}
538	                                    tone={val ? "success" : "subdued"}
539	                                  />
540	                                </InlineStack>
541	                              </Box>
542	                            );
543	                          })}
544	                        </InlineStack>
545	                      </Box>
546	                    ))}
547	                  </BlockStack>
548	                </Card>
549	              </BlockStack>
550	
551	              {/* FAQ */}
552	              <BlockStack gap="400">
553	                <Text as="h2" variant="headingLg">
554	                  Frequently Asked Questions
555	                </Text>
556	                <Card>
557	                  <BlockStack gap="400">
558	                    {[
559	                      {
560	                        q: "Can I switch plans anytime?",
561	                        a: "Yes. Upgrade instantly — new features activate immediately. Downgrades take effect at end of billing period.",
562	                      },
563	                      {
564	                        q: "What happens to my charts if I downgrade?",
565	                        a: "Charts are never deleted. On Free, only 3 most recent stay published. Re-publish anytime you upgrade.",
566	                      },
567	                      {
568	                        q: "Is there a free trial?",
569	                        a: "All paid plans include a 7-day free trial. The Free plan is permanent — not a trial.",
570	                      },
571	                      {
572	                        q: "Are there per-order fees?",
573	                        a: "Never. Flat monthly or annual pricing. No hidden charges, no matter how large your store grows.",
574	                      },
575	                      {
576	                        q: "Does the annual plan auto-renew?",
577	                        a: "Yes. Cancel anytime from Shopify Admin → Settings → Billing. No cancellation fees.",
578	                      },
579	                    ].map((faq, i) => (
580	                      <BlockStack key={i} gap="100">
581	                        <Text as="p" variant="bodyMd" fontWeight="bold">
582	                          {faq.q}
583	                        </Text>
584	                        <Text as="p" variant="bodyMd" tone="subdued">
585	                          {faq.a}
586	                        </Text>
587	                        {i < 4 && <Divider />}
588	                      </BlockStack>
589	                    ))}
590	                  </BlockStack>
591	                </Card>
592	              </BlockStack>
593	            </BlockStack>
594	          </Layout.Section>
595	        </Layout>
596	      </Box>
597	
598	      {/* Downgrade confirmation modal */}
599	      <Modal
600	        open={cancelModalOpen}
601	        onClose={() => setCancelModalOpen(false)}
602	        title="Downgrade to Free plan?"
603	        primaryAction={{
604	          content: "Yes, downgrade",
605	          destructive: true,
606	          onAction: handleConfirmCancel,
607	          loading: isFetching,
608	        }}
609	        secondaryActions={[
610	          {
611	            content: "Keep current plan",
612	            onAction: () => setCancelModalOpen(false),
613	          },
614	        ]}
615	      >
616	        <Modal.Section>
617	          <BlockStack gap="400">
618	            <Text as="p" variant="bodyMd">
619	              Downgrading to Free will immediately remove access to:
620	            </Text>
621	            <BlockStack gap="200">
622	              {[
623	                "Unlimited size charts — limited to 3",
624	                "CSV import / export",
625	                "Auto-assignment rules",
626	                "Analytics dashboard",
627	                "AI size recommender",
628	                "Priority support",
629	                "Return attribution",
630	              ].map((item) => (
631	                <InlineStack key={item} gap="200" blockAlign="start" wrap={false}>
632	                  <Text as="span" variant="bodyMd" tone="subdued">
633	                    ·
634	                  </Text>
635	                  <Text as="p" variant="bodyMd">
636	                    {item}
637	                  </Text>
638	                </InlineStack>
639	              ))}
640	            </BlockStack>
641	            <Banner tone="warning">
642	              <Text as="p" variant="bodyMd">
643	                Charts beyond the 3-chart limit will remain saved but become unpublished
644	                until you upgrade again.
645	              </Text>
646	            </Banner>
647	          </BlockStack>
648	        </Modal.Section>
649	      </Modal>
650	    </Page>
651	  );
652	}
