33	export const loader = async ({ request }: LoaderFunctionArgs) => {
34	  const { session } = await authenticate.admin(request);
35	  const shop = session.shop;
36	
37	  const [
38	    chartCount,
39	    assignmentCount,
40	    widgetConfig,
41	    recommenderConfig,
42	    subscription,
43	  ] = await Promise.all([
44	    db.sizeChart.count({ where: { shop } }),
45	    db.chartAssignment.count({ where: { shop } }),
46	    db.widgetConfig.findUnique({ where: { shop } }),
47	    db.recommenderConfig.findUnique({ where: { shop } }),
48	    db.subscription.findUnique({ where: { shop } }),
49	  ]);
50	
51	  const plan = getPlan(subscription?.planId ?? "free");
52	
53	  return {
54	    shop,
55	    chartCount,
56	    assignmentCount,
57	    hasWidgetConfig: widgetConfig !== null,
58	    widgetDisplayMode: widgetConfig?.displayMode ?? null,
59	    hasRecommenderConfig: recommenderConfig !== null,
60	    recommenderEnabled: recommenderConfig?.enabled ?? false,
61	    plan,
62	    isPriority: hasFeature(plan.id, "prioritySupport"),
63	    isFreePlan: plan.id === "free",
64	  };
65	};
