import { useState, useEffect, useCallback } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, useNavigate } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { PLANS, getPlan } from "../lib/plans";
import { createSubscription, cancelSubscription } from "../lib/billing.server";
import type { Plan } from "../lib/plans";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  ButtonGroup,
  Divider,
  Box,
  Banner,
  Icon,
  Modal,
  InlineGrid,
} from "@shopify/polaris";
import {
  CheckCircleIcon,
  XCircleIcon,
  StarIcon,
  LockIcon,
  RefreshIcon,
  ChatIcon,
} from "@shopify/polaris-icons";

// ─── Plan display data ──────────────────────────────────────────────────────

const PLAN_ORDER = ["free", "starter", "growth", "pro"] as const;

const PLAN_DESCRIPTIONS: Record<string, string> = {
  free: "Get started — no credit card required",
  starter: "Essential tools for growing stores",
  growth: "AI-powered sizing for serious brands",
  pro: "Enterprise-grade power and control",
};

// ─── Feature rows for plan cards ────────────────────────────────────────────

interface PlanFeatureDef {
  label: string;
  key: keyof Plan["limits"] | null;
  freeValue?: string;
  starterValue?: string;
  growthValue?: string;
  proValue?: string;
}

const PLAN_FEATURE_DEFS: PlanFeatureDef[] = [
  {
    label: "Published size charts",
    key: "maxCharts",
    freeValue: "3 charts",
    starterValue: "Unlimited",
    growthValue: "Unlimited",
    proValue: "Unlimited",
  },
  { label: "All templates included", key: null, freeValue: "yes", starterValue: "yes", growthValue: "yes", proValue: "yes" },
  { label: "CSV import / export", key: "csvImport" },
  { label: "Auto-assignment rules", key: "autoAssign" },
  { label: "Image support in charts", key: "imageInCharts" },
  { label: "Translate & Adapt (i18n)", key: "translateAdapt" },
  { label: "Analytics dashboard", key: "analytics" },
  { label: "Dedicated sizing page", key: "dedicatedSizingPage" },
  { label: "Basic AI recommender", key: "aiRecommender" },
  { label: "Advanced ML recommender", key: "advancedAi" },
  { label: "Return attribution", key: "returnAttribution" },
  { label: "Priority support (<2hr)", key: "prioritySupport" },
  { label: "Multi-store sync", key: "multiStore" },
];

// ─── Feature rows for comparison table ──────────────────────────────────────

const FEATURE_ROWS: { label: string; key: keyof Plan["limits"] }[] = [
  { label: "Published size charts", key: "maxCharts" },
  { label: "CSV import / export", key: "csvImport" },
  { label: "Auto-assignment rules", key: "autoAssign" },
  { label: "Image support in charts", key: "imageInCharts" },
  { label: "Translate & Adapt (i18n)", key: "translateAdapt" },
  { label: "Analytics dashboard", key: "analytics" },
  { label: "Dedicated sizing page", key: "dedicatedSizingPage" },
  { label: "AI size recommender", key: "aiRecommender" },
  { label: "Advanced ML recommender", key: "advancedAi" },
  { label: "Return attribution", key: "returnAttribution" },
  { label: "Priority support (<2hr)", key: "prioritySupport" },
  { label: "Multi-store sync", key: "multiStore" },
];

// ─── FAQ data ────────────────────────────────────────────────────────────────

const FAQS: { q: string; a: string }[] = [
  {
    q: "Can I change plans anytime?",
    a: "Yes, upgrade or downgrade instantly. Upgrades take effect immediately. Downgrades apply at the end of the billing cycle so you always get what you paid for.",
  },
  {
    q: "Is there a free trial?",
    a: "Every paid plan includes a 7-day free trial. Your card is not charged until the trial ends, and you can cancel before then with no cost.",
  },
  {
    q: "What happens when I hit my chart limit?",
    a: "On the Free plan, you can still edit and manage your existing 3 charts — you just cannot publish a 4th until you upgrade. No charts are ever deleted automatically.",
  },
  {
    q: "Do you charge per order?",
    a: "Never. Flat monthly pricing, no hidden fees, no per-order charges. Your bill stays predictable no matter how large your store grows.",
  },
  {
    q: "Can I cancel anytime?",
    a: "Yes, cancel with one click from Shopify Admin → Settings → Billing. No cancellation fees, no lock-in periods.",
  },
];

// ─── Loader ─────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const subscription = await db.subscription.findUnique({
    where: { shop: session.shop },
  });
  return {
    currentPlan: getPlan(subscription?.planId ?? "free"),
    billingInterval: subscription?.billingInterval ?? "monthly",
    plans: PLANS,
  };
};

// ─── Action ─────────────────────────────────────────────────────────────────

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session, admin } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  const billingContext = { admin, session: { shop } };

  try {
    if (intent === "subscribe") {
      const planId = formData.get("planId") as string;
      const interval = (formData.get("interval") as string) || "monthly";
      const plan = getPlan(planId);

      if (plan.price === 0) {
        // Downgrade to free — cancel existing Shopify subscription if any
        try {
          await cancelSubscription(billingContext);
        } catch {
          // No active subscription to cancel — that's fine
        }
        await db.subscription.upsert({
          where: { shop },
          update: { planId: "free", status: "active", billingInterval: "monthly", shopifySubscriptionId: null },
          create: { shop, planId: "free", billingInterval: "monthly", status: "active" },
        });
        return { ok: true, message: "Switched to Free plan" };
      }

      // Create Shopify subscription — returns a confirmation URL
      const billingInterval = interval === "annual" ? "annual" as const : "monthly" as const;
      const { confirmationUrl } = await createSubscription(
        billingContext,
        planId,
        billingInterval,
      );

      // Redirect merchant to Shopify's hosted billing approval page
      return { ok: true, message: `Redirecting to billing approval...`, confirmationUrl };
    }

    if (intent === "cancel") {
      await cancelSubscription(billingContext);
      return { ok: true, message: "Subscription cancelled. You are now on the Free plan." };
    }

    return { error: "Unknown action" };
  } catch (error) {
    return { error: error instanceof Error ? error.message : "An unexpected error occurred" };
  }
};

// ─── Feature cell helper ─────────────────────────────────────────────────────

function FeatureCell({ value, plan }: { value: boolean | number | string; plan: Plan; key?: string }) {
  if (typeof value === "number") {
    return (
      <Text as="span" variant="bodyMd" fontWeight="semibold">
        {value === -1 ? "Unlimited" : String(value)}
      </Text>
    );
  }
  if (typeof value === "string") {
    if (value === "yes") {
      return <Icon source={CheckCircleIcon} tone="success" />;
    }
    return (
      <Text as="span" variant="bodySm" tone="subdued">
        {value}
      </Text>
    );
  }
  return <Icon source={value ? CheckCircleIcon : XCircleIcon} tone={value ? "success" : "subdued"} />;
}

// ─── Plan feature row (inside card) ─────────────────────────────────────────

function PlanFeatureRow({
  def,
  plan,
}: {
  def: PlanFeatureDef;
  plan: Plan;
}) {
  let display: boolean | number | string;

  if (def.key === null) {
    // All-yes feature
    display = "yes";
  } else if (def.key === "maxCharts") {
    display = plan.limits.maxCharts;
  } else {
    display = plan.limits[def.key] as boolean;
  }

  const isPositive =
    display === "yes" ||
    (typeof display === "boolean" && display) ||
    (typeof display === "number" && display !== 0);

  return (
    <InlineStack gap="200" blockAlign="start" wrap={false}>
      <Box minWidth="20px">
        <Icon
          source={isPositive ? CheckCircleIcon : XCircleIcon}
          tone={isPositive ? "success" : "subdued"}
        />
      </Box>
      <BlockStack gap="0">
        <Text as="span" variant="bodySm">
          {def.label}
        </Text>
        {typeof display === "number" && display !== -1 && plan.id === "free" && (
          <Text as="span" variant="bodySm" tone="subdued">
            Up to {display}
          </Text>
        )}
      </BlockStack>
    </InlineStack>
  );
}

// ─── Plan card ───────────────────────────────────────────────────────────────

interface PlanCardProps {
  plan: Plan;
  isAnnual: boolean;
  currentTier: string;
  onSubscribe: (planId: string) => void;
  onRequestCancel: () => void;
  isLoading: boolean;
}

function PlanCard({
  plan,
  isAnnual,
  currentTier,
  onSubscribe,
  onRequestCancel,
  isLoading,
}: PlanCardProps) {
  const isCurrent = currentTier === plan.id;
  const isMostPopular = plan.id === "growth";
  const tierIndex = PLAN_ORDER.indexOf(plan.id as (typeof PLAN_ORDER)[number]);
  const currentIndex = PLAN_ORDER.indexOf(currentTier as (typeof PLAN_ORDER)[number]);
  const isUpgrade = tierIndex > currentIndex;

  const displayPrice = isAnnual
    ? (plan.annualPrice / 12).toFixed(2)
    : plan.price.toFixed(2);

  let buttonContent = "Start free trial";
  let buttonVariant: "primary" | "secondary" | undefined = "primary";
  let buttonTone: "critical" | undefined = undefined;
  let showButton = true;

  if (isCurrent) {
    buttonContent = "Current plan";
    buttonVariant = "secondary";
  } else if (plan.price === 0) {
    if (currentTier === "free") {
      showButton = false;
    } else {
      buttonContent = "Downgrade to Free";
      buttonVariant = undefined;
      buttonTone = "critical";
    }
  } else if (isUpgrade) {
    buttonContent = `Upgrade to ${plan.name}`;
    buttonVariant = "primary";
  } else {
    buttonContent = `Switch to ${plan.name}`;
    buttonVariant = undefined;
  }

  const handleClick = () => {
    if (isCurrent) return;
    if (plan.price === 0) {
      onRequestCancel();
    } else {
      onSubscribe(plan.id);
    }
  };

  return (
    <Card>
      <BlockStack gap="400">
        {/* Plan name + badges */}
        <BlockStack gap="150">
          <InlineStack align="space-between" blockAlign="start">
            <Text as="h3" variant="headingMd" fontWeight="bold">
              {plan.name}
            </Text>
            <InlineStack gap="100">
              {isMostPopular && !isCurrent && (
                <Badge tone="attention" icon={StarIcon}>
                  Most popular
                </Badge>
              )}
              {isCurrent && <Badge tone="success">Your plan</Badge>}
            </InlineStack>
          </InlineStack>
          <Text as="p" variant="bodySm" tone="subdued">
            {PLAN_DESCRIPTIONS[plan.id] ?? ""}
          </Text>
        </BlockStack>

        <Divider />

        {/* Price */}
        <BlockStack gap="100">
          {plan.price === 0 ? (
            <>
              <Text as="p" variant="headingXl" fontWeight="bold">
                Free
              </Text>
              <Text as="p" variant="bodySm" tone="subdued">
                forever — no credit card
              </Text>
            </>
          ) : (
            <>
              <InlineStack gap="100" blockAlign="baseline">
                <Text as="p" variant="headingXl" fontWeight="bold">
                  ${displayPrice}
                </Text>
                <Text as="p" variant="bodySm" tone="subdued">
                  /mo
                </Text>
              </InlineStack>
              {isAnnual ? (
                <Text as="p" variant="bodySm" tone="subdued">
                  ${plan.annualPrice.toFixed(2)} billed annually
                </Text>
              ) : (
                <Text as="p" variant="bodySm" tone="subdued">
                  or ${(plan.annualPrice / 12).toFixed(2)}/mo billed annually
                </Text>
              )}
            </>
          )}
        </BlockStack>

        {/* CTA button */}
        {showButton && (
          <Button
            variant={buttonVariant}
            tone={buttonTone}
            onClick={handleClick}
            disabled={isCurrent}
            loading={isLoading && !isCurrent}
            fullWidth
          >
            {buttonContent}
          </Button>
        )}

        <Divider />

        {/* Features list — all features with check/cross */}
        <BlockStack gap="250">
          {PLAN_FEATURE_DEFS.map((def) => (
            <PlanFeatureRow key={def.label} def={def} plan={plan} />
          ))}
        </BlockStack>
      </BlockStack>
    </Card>
  );
}

// ─── FAQ item ─────────────────────────────────────────────────────────────────

function FaqItem({ q, a, isLast }: { q: string; a: string; isLast: boolean }) {
  const [open, setOpen] = useState(false);

  return (
    <BlockStack gap="0">
      <Box paddingBlock="300">
        <InlineStack align="space-between" blockAlign="center">
          <Text as="p" variant="bodyMd" fontWeight="semibold">
            {q}
          </Text>
          <Button
            variant="plain"
            onClick={() => setOpen((v) => !v)}
            ariaExpanded={open}
          >
            {open ? "Hide" : "Show"}
          </Button>
        </InlineStack>
        {open && (
          <Box paddingBlockStart="200">
            <Text as="p" variant="bodyMd" tone="subdued">
              {a}
            </Text>
          </Box>
        )}
      </Box>
      {!isLast && <Divider />}
    </BlockStack>
  );
}

// ─── Trust badge ──────────────────────────────────────────────────────────────

function TrustBadge({ icon, label }: { icon: React.ComponentProps<typeof Icon>["source"]; label: string }) {
  return (
    <InlineStack gap="200" blockAlign="center">
      <Icon source={icon} tone="subdued" />
      <Text as="span" variant="bodySm" tone="subdued">
        {label}
      </Text>
    </InlineStack>
  );
}

// ─── Page ────────────────────────────────────────────────────────────────────

export default function PricingPage() {
  const { currentPlan, billingInterval: initialInterval, plans } =
    useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const navigate = useNavigate();
  const shopify = useAppBridge();

  const [isAnnual, setIsAnnual] = useState(initialInterval === "annual");
  const [cancelModalOpen, setCancelModalOpen] = useState(false);

  const isFetching = fetcher.state !== "idle";

  useEffect(() => {
    const data = fetcher.data;
    if (data && "ok" in data && data.ok) {
      if ("confirmationUrl" in data && typeof data.confirmationUrl === "string") {
        if (window.top) {
          window.top.location.href = data.confirmationUrl;
        } else {
          window.location.href = data.confirmationUrl;
        }
        return;
      }
      shopify.toast.show(data.message ?? "Plan updated");
    } else if (data && "error" in data) {
      shopify.toast.show(data.error ?? "Error", { isError: true });
    }
  }, [fetcher.data, shopify]);

  const handleSubscribe = useCallback(
    (planId: string) => {
      fetcher.submit(
        { intent: "subscribe", planId, interval: isAnnual ? "annual" : "monthly" },
        { method: "post" },
      );
    },
    [fetcher, isAnnual],
  );

  const handleConfirmCancel = useCallback(() => {
    setCancelModalOpen(false);
    fetcher.submit({ intent: "cancel" }, { method: "post" });
  }, [fetcher]);

  const orderedPlans = PLAN_ORDER.map((id) => plans.find((p) => p.id === id)).filter(
    (p): p is Plan => p !== undefined,
  );

  const actionError =
    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;

  return (
    <Page
      title="Plans & Pricing"
      subtitle="Simple, transparent pricing. No hidden fees."
      backAction={{ onAction: () => navigate("/app") }}
    >
      <Box paddingBlockEnd="1600">
        <Layout>
          {/* Error banner */}
          {actionError && (
            <Layout.Section>
              <Banner tone="critical" title="Billing error">
                <Text as="p" variant="bodyMd">
                  {actionError}
                </Text>
              </Banner>
            </Layout.Section>
          )}

          <Layout.Section>
            <BlockStack gap="800">

              {/* ── Billing toggle ─────────────────────────────────────────── */}
              <BlockStack gap="300" inlineAlign="center">
                <ButtonGroup variant="segmented">
                  <Button pressed={!isAnnual} onClick={() => setIsAnnual(false)}>
                    Monthly
                  </Button>
                  <Button pressed={isAnnual} onClick={() => setIsAnnual(true)}>
                    Annual
                  </Button>
                </ButtonGroup>
                {isAnnual ? (
                  <Badge tone="success">Save 17% — 2 months free</Badge>
                ) : (
                  <Text as="p" variant="bodySm" tone="subdued">
                    Switch to annual and save 17%
                  </Text>
                )}
              </BlockStack>

              {/* ── Plan cards ────────────────────────────────────────────── */}
              <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
                {orderedPlans.map((plan) => (
                  <PlanCard
                    key={plan.id}
                    plan={plan}
                    isAnnual={isAnnual}
                    currentTier={currentPlan.id}
                    onSubscribe={handleSubscribe}
                    onRequestCancel={() => setCancelModalOpen(true)}
                    isLoading={isFetching}
                  />
                ))}
              </InlineGrid>

              {/* Trial + money-back footnote */}
              <BlockStack gap="200" inlineAlign="center">
                <Text as="p" variant="bodySm" tone="subdued" alignment="center">
                  All paid plans include a 7-day free trial. No credit card charged until the trial ends.
                </Text>
                <Text as="p" variant="bodySm" tone="subdued" alignment="center">
                  30-day money-back guarantee. Cancel anytime from Shopify billing.
                </Text>
              </BlockStack>

              {/* ── Trust strip ───────────────────────────────────────────── */}
              <Card>
                <InlineStack align="space-evenly" wrap gap="400">
                  <TrustBadge icon={LockIcon} label="Secure Shopify checkout" />
                  <TrustBadge icon={RefreshIcon} label="30-day money-back guarantee" />
                  <TrustBadge icon={ChatIcon} label="Support within 24 hours" />
                </InlineStack>
              </Card>

              {/* ── Why switch section ────────────────────────────────────── */}
              <BlockStack gap="400">
                <Text as="h2" variant="headingLg">
                  Why merchants switch to us
                </Text>
                <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
                  <Card>
                    <BlockStack gap="200">
                      <Text as="h3" variant="headingSm" fontWeight="bold">
                        No per-order fees
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        Competitors charge per order — costs balloon as your store grows.
                        We use simple flat monthly pricing. Your bill stays predictable.
                      </Text>
                    </BlockStack>
                  </Card>
                  <Card>
                    <BlockStack gap="200">
                      <Text as="h3" variant="headingSm" fontWeight="bold">
                        Mobile-first widget
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        iOS Safari bugs are the #1 complaint in competitor reviews.
                        Our widget is pixel-perfect on every device.
                      </Text>
                    </BlockStack>
                  </Card>
                  <Card>
                    <BlockStack gap="200">
                      <Text as="h3" variant="headingSm" fontWeight="bold">
                        Set up in 5 minutes
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        Auto-detect product types, suggest templates, and auto-assign charts.
                        Most merchants publish their first chart in under 3 minutes.
                      </Text>
                    </BlockStack>
                  </Card>
                </InlineGrid>
              </BlockStack>

              {/* ── Full feature comparison table ────────────────────────── */}
              <BlockStack gap="400">
                <Text as="h2" variant="headingLg">
                  Full feature comparison
                </Text>
                <Card>
                  <BlockStack gap="0">
                    {/* Header row */}
                    <Box paddingBlockEnd="400">
                      <InlineStack align="space-between">
                        <Box minWidth="220px">
                          <Text as="p" variant="bodySm" tone="subdued">
                            Feature
                          </Text>
                        </Box>
                        {orderedPlans.map((plan) => (
                          <Box key={plan.id} minWidth="100px">
                            <BlockStack gap="100" inlineAlign="center">
                              <Text as="p" variant="headingSm" fontWeight="bold">
                                {plan.name}
                              </Text>
                              <Text as="p" variant="bodySm" tone="subdued">
                                {plan.price === 0
                                  ? "Free"
                                  : isAnnual
                                    ? `$${(plan.annualPrice / 12).toFixed(2)}/mo`
                                    : `$${plan.price}/mo`}
                              </Text>
                            </BlockStack>
                          </Box>
                        ))}
                      </InlineStack>
                    </Box>

                    <Divider />

                    {/* Feature rows */}
                    {FEATURE_ROWS.map((row, i) => (
                      <Box key={row.key} paddingBlock="300">
                        <InlineStack align="space-between" blockAlign="center">
                          <Box minWidth="220px">
                            <Text as="p" variant="bodyMd">
                              {row.label}
                            </Text>
                          </Box>
                          {orderedPlans.map((plan) => {
                            const val = plan.limits[row.key];
                            return (
                              <Box key={plan.id} minWidth="100px">
                                <InlineStack align="center">
                                  <FeatureCell value={val} plan={plan} />
                                </InlineStack>
                              </Box>
                            );
                          })}
                        </InlineStack>
                        {i < FEATURE_ROWS.length - 1 && <Box paddingBlockStart="300"><Divider /></Box>}
                      </Box>
                    ))}
                  </BlockStack>
                </Card>
              </BlockStack>

              {/* ── FAQ section ───────────────────────────────────────────── */}
              <BlockStack gap="400">
                <Text as="h2" variant="headingLg">
                  Frequently asked questions
                </Text>
                <Card>
                  <BlockStack gap="0">
                    {FAQS.map((faq, i) => (
                      <FaqItem
                        key={i}
                        q={faq.q}
                        a={faq.a}
                        isLast={i === FAQS.length - 1}
                      />
                    ))}
                  </BlockStack>
                </Card>
              </BlockStack>

            </BlockStack>
          </Layout.Section>
        </Layout>
      </Box>

      {/* ── Downgrade confirmation modal ──────────────────────────────────── */}
      <Modal
        open={cancelModalOpen}
        onClose={() => setCancelModalOpen(false)}
        title="Downgrade to Free plan?"
        primaryAction={{
          content: "Yes, downgrade",
          destructive: true,
          onAction: handleConfirmCancel,
          loading: isFetching,
        }}
        secondaryActions={[
          {
            content: "Keep current plan",
            onAction: () => setCancelModalOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            <Text as="p" variant="bodyMd">
              Downgrading to Free will remove access to:
            </Text>
            <BlockStack gap="200">
              {[
                "Unlimited size charts (limited to 3)",
                "CSV import / export",
                "Auto-assignment rules",
                "Analytics dashboard",
                "AI size recommender",
                "Priority support",
                "Return attribution",
              ].map((item) => (
                <InlineStack key={item} gap="200" blockAlign="start" wrap={false}>
                  <Box>
                    <Icon source={XCircleIcon} tone="subdued" />
                  </Box>
                  <Text as="p" variant="bodyMd">
                    {item}
                  </Text>
                </InlineStack>
              ))}
            </BlockStack>
            <Banner tone="warning">
              <Text as="p" variant="bodyMd">
                Charts beyond the 3-chart limit will remain saved but become unpublished
                until you upgrade again.
              </Text>
            </Banner>
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

import { useEffect, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, useNavigate } from "react-router";
