interface StatusItemProps {
  label: string;
  configured: boolean;
  configuredLabel: string;
  notConfiguredLabel: string;
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [
    chartCount,
    activeChartCount,
    assignmentCount,
    widgetConfig,
    recommenderConfig,
    subscription,
  ] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.sizeChart.count({ where: { shop, status: "active" } }),
    db.chartAssignment.count({ where: { shop } }),
    db.widgetConfig.findUnique({ where: { shop } }),
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  return {
    shop,
    chartCount,
    activeChartCount,
    assignmentCount,
    hasWidgetConfig: widgetConfig !== null,
    widgetDisplayMode: widgetConfig?.displayMode ?? null,
    hasRecommenderConfig: recommenderConfig !== null,
    recommenderEnabled: recommenderConfig?.enabled ?? false,
    plan,
    isPriority: hasFeature(plan.id, "prioritySupport"),
    isFreePlan: plan.id === "free",
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "export-data": {
        const charts = await db.sizeChart.findMany({
          where: { shop },
          include: { assignments: true },
        });
        const payload = {
          exportedAt: new Date().toISOString(),
          shop,
          charts: charts.map((c) => ({
            id: c.id,
            name: c.name,
            type: c.type,
            category: c.category,
            data: c.data,
            isDefault: c.isDefault,
            status: c.status,
            createdAt: c.createdAt.toISOString(),
            assignments: c.assignments.map((a) => ({
              assignmentType: a.assignmentType,
              assignmentValue: a.assignmentValue,
            })),
          })),
        };
        return {
          ok: true,
          intent: "export-data",
          message: `${charts.length} chart${charts.length === 1 ? "" : "s"} exported`,
          exportData: JSON.stringify(payload, null, 2),
        };
      }

      case "import-data": {
        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        if (!hasFeature(plan.id, "csvImport")) {
          return { error: "Import requires the Starter plan or above", intent: "import-data" };
        }

        const jsonRaw = formData.get("importJson") as string;
        if (!jsonRaw?.trim()) {
          return { error: "No JSON data provided", intent: "import-data" };
        }
        let parsed: {
          charts?: Array<{
            name: string;
            type?: string;
            category?: string;
            data?: string;
            isDefault?: boolean;
            status?: string;
            assignments?: Array<{ assignmentType: string; assignmentValue: string }>;
          }>;
        };
        try {
          parsed = JSON.parse(jsonRaw) as typeof parsed;
        } catch {
          return { error: "Invalid JSON format", intent: "import-data" };
        }
        if (!Array.isArray(parsed.charts)) {
          return { error: "JSON must contain a 'charts' array", intent: "import-data" };
        }
        let imported = 0;
        for (const chart of parsed.charts) {
          if (!chart.name) continue;
          const existing = await db.sizeChart.findFirst({
            where: { shop, name: chart.name },
          });
          if (existing) continue;
          await db.sizeChart.create({
            data: {
              shop,
              name: chart.name,
              type: chart.type ?? "table",
              category: chart.category ?? "general",
              data: chart.data ?? "{}",
              isDefault: chart.isDefault ?? false,
              status: chart.status ?? "draft",
              assignments: chart.assignments
                ? {
                    create: chart.assignments.map((a) => ({
                      shop,
                      assignmentType: a.assignmentType,
                      assignmentValue: a.assignmentValue,
                    })),
                  }
                : undefined,
            },
          });
          imported++;
        }
        return {
          ok: true,
          intent: "import-data",
          message: `${imported} chart${imported === 1 ? "" : "s"} imported successfully`,
        };
      }

      case "reset-widget": {
        await db.widgetConfig.deleteMany({ where: { shop } });
        return { ok: true, intent: "reset-widget", message: "Widget settings reset to defaults" };
      }

      case "reset-analytics": {
        const deleted = await db.analyticsEvent.deleteMany({ where: { shop } });
        return {
          ok: true,
          intent: "reset-analytics",
          message: `${deleted.count} analytics event${deleted.count === 1 ? "" : "s"} cleared`,
        };
      }

      case "delete-all-charts": {
        const confirm = formData.get("confirmText") as string;
        if (confirm !== "DELETE") {
          return { error: "Type DELETE to confirm", intent: "delete-all-charts" };
        }
        await db.chartAssignment.deleteMany({ where: { shop } });
        const deleted = await db.sizeChart.deleteMany({ where: { shop } });
        return {
          ok: true,
          intent: "delete-all-charts",
          message: `${deleted.count} chart${deleted.count === 1 ? "" : "s"} deleted`,
        };
      }

      case "reset-app": {
        const confirm = formData.get("confirmText") as string;
        if (confirm !== "DELETE") {
          return { error: "Type DELETE to confirm", intent: "reset-app" };
        }
        await Promise.all([
          db.widgetConfig.deleteMany({ where: { shop } }),
          db.recommenderConfig.deleteMany({ where: { shop } }),
          db.analyticsEvent.deleteMany({ where: { shop } }),
        ]);
        return {
          ok: true,
          intent: "reset-app",
          message: "App data reset. Widget, recommender and analytics cleared.",
        };
      }

      default:
        return { error: "Unknown action", intent };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "An unexpected error occurred";
    return { error: message, intent };
  }
};

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

function SectionHeader({
  icon,
  title,
  description,
}: {
  icon: React.ComponentProps<typeof Icon>["source"];
  title: string;
  description?: string;
}) {
  return (
    <InlineStack gap="300" blockAlign="center">
      <Box
        background="bg-surface-secondary"
        borderRadius="200"
        padding="200"
      >
        <Icon source={icon} tone="base" />
      </Box>
      <BlockStack gap="0">
        <Text as="h2" variant="headingMd" fontWeight="bold">
          {title}
        </Text>
        {description && (
          <Text as="p" variant="bodySm" tone="subdued">
            {description}
          </Text>
        )}
      </BlockStack>
    </InlineStack>
  );
}

function StatusItem({ label, configured, configuredLabel, notConfiguredLabel }: StatusItemProps) {
  return (
    <InlineStack gap="200" blockAlign="center" wrap={false}>
      <Icon
        source={configured ? CheckCircleIcon : XCircleIcon}
        tone={configured ? "success" : "subdued"}
      />
      <Text as="span" variant="bodyMd">
        {label}
      </Text>
      <Badge tone={configured ? "success" : "enabled"}>
        {configured ? configuredLabel : notConfiguredLabel}
      </Badge>
    </InlineStack>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

export default function Settings() {
  const {
    shop,
    chartCount,
    activeChartCount,
    assignmentCount,
    hasWidgetConfig,
    widgetDisplayMode,
    hasRecommenderConfig,
    recommenderEnabled,
    plan,
    isPriority,
    isFreePlan,
  } = useLoaderData<typeof loader>();

  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();
  const isLoading = fetcher.state !== "idle";

  // Preferences (client-side for now — can be persisted in WidgetConfig)
  const [unitSystem, setUnitSystem] = useState<string>("cm");
  const [defaultCategory, setDefaultCategory] = useState<string>("general");
  const [autoPublish, setAutoPublish] = useState<boolean>(false);

  // Import text area
  const [importJson, setImportJson] = useState<string>("");

  // Modal states
  const [resetAnalyticsOpen, setResetAnalyticsOpen] = useState(false);
  const [deleteChartsOpen, setDeleteChartsOpen] = useState(false);
  const [resetAppOpen, setResetAppOpen] = useState(false);

  // Confirm text for destructive modals
  const [deleteChartsConfirm, setDeleteChartsConfirm] = useState("");
  const [resetAppConfirm, setResetAppConfirm] = useState("");

  // Export download trigger
  const [exportedJson, setExportedJson] = useState<string | null>(null);

  useEffect(() => {
    if (!fetcher.data) return;

    if ("ok" in fetcher.data) {
      shopify.toast.show(fetcher.data.message ?? "Done");

      if (fetcher.data.intent === "export-data" && "exportData" in fetcher.data) {
        setExportedJson(fetcher.data.exportData as string);
      }
      if (fetcher.data.intent === "import-data") {
        setImportJson("");
      }
      if (fetcher.data.intent === "delete-all-charts") {
        setDeleteChartsConfirm("");
        setDeleteChartsOpen(false);
      }
      if (fetcher.data.intent === "reset-app") {
        setResetAppConfirm("");
        setResetAppOpen(false);
      }
      if (fetcher.data.intent === "reset-analytics") {
        setResetAnalyticsOpen(false);
      }
    } else if ("error" in fetcher.data) {
      shopify.toast.show(fetcher.data.error ?? "An error occurred", { isError: true });
    }
  }, [fetcher.data, shopify]);

  // Trigger browser download when export data is ready
  useEffect(() => {
    if (!exportedJson) return;
    const blob = new Blob([exportedJson], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `size-charts-${shop}-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setExportedJson(null);
  }, [exportedJson, shop]);

  const submitIntent = (intent: string, extra?: Record<string, string>) => {
    const fd = new FormData();
    fd.set("intent", intent);
    if (extra) {
      for (const [k, v] of Object.entries(extra)) fd.set(k, v);
    }
    fetcher.submit(fd, { method: "post" });
  };

  const CATEGORIES = [
    "general",
    "tops",
    "bottoms",
    "dresses",
    "shoes",
    "kids",
    "rings",
    "sportswear",
    "outerwear",
  ];

  const unitOptions = [
    { label: "Centimeters (cm)", value: "cm" },
    { label: "Inches (in)", value: "in" },
  ];

  const categoryOptions = CATEGORIES.map((cat) => ({
    label: cat.charAt(0).toUpperCase() + cat.slice(1),
    value: cat,
  }));

  const currentLoadingIntent =
    isLoading && fetcher.formData ? (fetcher.formData.get("intent") as string) : null;

  return (
    <Page
      title="Settings"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={
        <Button variant="primary" onClick={() => navigate("/app/pricing")}>
          {isFreePlan ? "Upgrade plan" : "Manage billing"}
        </Button>
      }
    >
      <BlockStack gap="600">

        {/* ================================================================ */}
        {/* SECTION 1 — App Overview                                          */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="500">
            <SectionHeader
              icon={StoreIcon}
              title="App Overview"
              description="Your store snapshot and current plan status."
            />

            <Divider />

            <InlineGrid columns={{ xs: 1, sm: 2 }} gap="500">
              {/* Store info */}
              <BlockStack gap="300">
                <BlockStack gap="100">
                  <Text as="p" variant="bodySm" tone="subdued">
                    Store domain
                  </Text>
                  <Text as="p" variant="bodyMd" fontWeight="semibold">
                    {shop}
                  </Text>
                </BlockStack>

                <BlockStack gap="100">
                  <Text as="p" variant="bodySm" tone="subdued">
                    Current plan
                  </Text>
                  <InlineStack gap="200" blockAlign="center">
                    <Badge tone={isFreePlan ? "enabled" : "success"}>{plan.name}</Badge>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      {plan.price === 0 ? "Free forever" : `$${plan.price}/mo`}
                    </Text>
                  </InlineStack>
                </BlockStack>

                {isPriority && (
                  <Badge tone="success">Priority support active</Badge>
                )}
              </BlockStack>

              {/* Quick stats */}
              <BlockStack gap="300">
                <InlineStack gap="400" blockAlign="center">
                  <Icon source={ChartVerticalIcon} tone="subdued" />
                  <BlockStack gap="0">
                    <Text as="p" variant="bodyMd" fontWeight="semibold">
                      {chartCount} total charts
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      {activeChartCount} active
                    </Text>
                  </BlockStack>
                </InlineStack>

                <StatusItem
                  label="Widget"
                  configured={hasWidgetConfig}
                  configuredLabel="Configured"
                  notConfiguredLabel="Using defaults"
                />
                <StatusItem
                  label="Recommender"
                  configured={recommenderEnabled}
                  configuredLabel="Active"
                  notConfiguredLabel={hasRecommenderConfig ? "Disabled" : "Not set up"}
                />
                <InlineStack gap="200" blockAlign="center">
                  <Icon source={CheckCircleIcon} tone="subdued" />
                  <Text as="span" variant="bodyMd">Assignments</Text>
                  <Badge>{String(assignmentCount)} products assigned</Badge>
                </InlineStack>
              </BlockStack>
            </InlineGrid>

            {isFreePlan && (
              <Banner tone="info">
                <BlockStack gap="200">
                  <Text as="p" variant="bodyMd">
                    Upgrade for unlimited charts, CSV import/export, AI recommender, and analytics.
                  </Text>
                  <Button variant="primary" onClick={() => navigate("/app/pricing")}>
                    View upgrade options
                  </Button>
                </BlockStack>
              </Banner>
            )}
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 2 — Theme Extension                                       */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="500">
            <SectionHeader
              icon={CodeIcon}
              title="Theme Extension"
              description="Enable the size chart widget in your storefront theme."
            />

            <Divider />

            <BlockStack gap="400">
              <Text as="p" variant="bodyMd" tone="subdued">
                The size chart widget is delivered as a native Shopify theme app block.
                Follow these steps to activate it on your product pages:
              </Text>

              <List type="number" gap="loose">
                <List.Item>
                  Go to{" "}
                  <Text as="span" variant="bodyMd" fontWeight="semibold">
                    Online Store → Themes → Customize
                  </Text>
                </List.Item>
                <List.Item>
                  Navigate to a product page template and click{" "}
                  <Text as="span" variant="bodyMd" fontWeight="semibold">
                    Add block
                  </Text>
                </List.Item>
                <List.Item>
                  Search for{" "}
                  <Text as="span" variant="bodyMd" fontWeight="semibold">
                    "Size Chart"
                  </Text>{" "}
                  in the Apps section and add it
                </List.Item>
                <List.Item>
                  Position the block where you want it to appear, then{" "}
                  <Text as="span" variant="bodyMd" fontWeight="semibold">
                    Save and publish
                  </Text>
                </List.Item>
              </List>

              <InlineStack gap="300" blockAlign="center">
                <Button
                  variant="primary"
                  url={`https://${shop}/admin/themes/current/editor`}
                  target="_blank"
                >
                  Open theme editor
                </Button>
                <Button
                  variant="secondary"
                  onClick={() => navigate("/app/widget")}
                >
                  Customize widget
                </Button>
              </InlineStack>

              <Banner tone="info">
                <Text as="p" variant="bodyMd">
                  The widget automatically inherits your theme styles. No custom CSS required.
                  Mobile-first and accessible by default.
                </Text>
              </Banner>
            </BlockStack>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 3 — Data Management                                       */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="500">
            <SectionHeader
              icon={DatabaseIcon}
              title="Data Management"
              description="Export, import, or clear your size chart data."
            />

            <Divider />

            {/* Export */}
            <BlockStack gap="300">
              <Text as="h3" variant="headingSm" fontWeight="bold">
                Export data
              </Text>
              <Text as="p" variant="bodyMd" tone="subdued">
                Download all {chartCount} chart{chartCount === 1 ? "" : "s"} as a JSON file.
                Includes all assignments and layout data. Use to back up or migrate to another store.
              </Text>
              <InlineStack gap="200">
                <Button
                  onClick={() => submitIntent("export-data")}
                  loading={currentLoadingIntent === "export-data"}
                  disabled={chartCount === 0}
                >
                  Export all data (JSON)
                </Button>
              </InlineStack>
              {chartCount === 0 && (
                <Text as="p" variant="bodySm" tone="subdued">
                  No charts to export yet.
                </Text>
              )}
            </BlockStack>

            <Divider />

            {/* Import */}
            <BlockStack gap="300">
              <InlineStack gap="200" blockAlign="center">
                <Text as="h3" variant="headingSm" fontWeight="bold">
                  Import from JSON
                </Text>
                {!hasFeature(plan.id, "csvImport") && (
                  <Badge tone="warning">Starter plan required</Badge>
                )}
              </InlineStack>
              <Text as="p" variant="bodyMd" tone="subdued">
                Paste your exported JSON backup below. Charts with the same name are skipped to avoid duplicates.
              </Text>
              {!hasFeature(plan.id, "csvImport") && (
                <Banner tone="warning">
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Import is available on the Starter plan ($4.99/mo) and above.{" "}
                    <Button variant="plain" onClick={() => navigate("/app/pricing")}>
                      Upgrade now
                    </Button>
                  </Text>
                </Banner>
              )}
              <TextField
                label="Import JSON"
                labelHidden
                value={importJson}
                onChange={(value) => setImportJson(value)}
                placeholder='{"charts": [...]}'
                multiline={6}
                autoComplete="off"
                disabled={!hasFeature(plan.id, "csvImport")}
              />
              <InlineStack gap="200">
                <Button
                  variant="primary"
                  onClick={() => submitIntent("import-data", { importJson })}
                  loading={currentLoadingIntent === "import-data"}
                  disabled={!hasFeature(plan.id, "csvImport") || !importJson.trim()}
                >
                  Import charts
                </Button>
              </InlineStack>
            </BlockStack>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 4 — Default Preferences                                   */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="500">
            <SectionHeader
              icon={SettingsIcon}
              title="Default Preferences"
              description="Configure defaults applied when creating new size charts."
            />

            <Divider />

            <InlineGrid columns={{ xs: 1, sm: 2 }} gap="500">
              <BlockStack gap="200">
                <Text as="p" variant="bodyMd" fontWeight="semibold">
                  Default measurement unit
                </Text>
                <Text as="p" variant="bodySm" tone="subdued">
                  Sets the default for new charts. Customers can still switch between units.
                </Text>
                <Select
                  label="Default unit system"
                  labelHidden
                  options={unitOptions}
                  value={unitSystem}
                  onChange={(value) => setUnitSystem(value)}
                />
              </BlockStack>

              <BlockStack gap="200">
                <Text as="p" variant="bodyMd" fontWeight="semibold">
                  Default chart category
                </Text>
                <Text as="p" variant="bodySm" tone="subdued">
                  Pre-selected category when creating a chart from scratch.
                </Text>
                <Select
                  label="Default chart category"
                  labelHidden
                  options={categoryOptions}
                  value={defaultCategory}
                  onChange={(value) => setDefaultCategory(value)}
                />
              </BlockStack>
            </InlineGrid>

            <Divider />

            <InlineStack gap="400" blockAlign="center">
              <BlockStack gap="100">
                <Text as="p" variant="bodyMd" fontWeight="semibold">
                  Auto-publish new charts
                </Text>
                <Text as="p" variant="bodySm" tone="subdued">
                  New charts are set to Active immediately instead of Draft.
                </Text>
              </BlockStack>
              <Checkbox
                label="Auto-publish new charts"
                labelHidden
                checked={autoPublish}
                onChange={(checked) => setAutoPublish(checked)}
              />
            </InlineStack>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 5 — Danger Zone                                           */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="500">
            <SectionHeader
              icon={AlertTriangleIcon}
              title="Danger Zone"
              description="Irreversible actions. These cannot be undone."
            />

            <Divider />

            <Banner tone="critical">
              <Text as="p" variant="bodyMd">
                These actions permanently delete data. Make sure you export a backup first if needed.
              </Text>
            </Banner>

            <BlockStack gap="400">
              {/* Reset analytics */}
              <Card>
                <BlockStack gap="200">
                  <Text as="p" variant="bodyMd" fontWeight="semibold">
                    Clear analytics data
                  </Text>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Permanently delete all chart view events, recommendation events, and conversion data.
                  </Text>
                  <InlineStack gap="200">
                    <Button
                      tone="critical"
                      onClick={() => setResetAnalyticsOpen(true)}
                    >
                      Clear all analytics
                    </Button>
                  </InlineStack>
                </BlockStack>
              </Card>

              {/* Delete all charts */}
              <Card>
                <BlockStack gap="200">
                  <Text as="p" variant="bodyMd" fontWeight="semibold">
                    Delete all size charts
                  </Text>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Permanently delete all {chartCount} size chart{chartCount === 1 ? "" : "s"} and their
                    product assignments.
                  </Text>
                  <InlineStack gap="200">
                    <Button
                      tone="critical"
                      onClick={() => {
                        setDeleteChartsConfirm("");
                        setDeleteChartsOpen(true);
                      }}
                      disabled={chartCount === 0}
                    >
                      Delete all charts
                    </Button>
                  </InlineStack>
                </BlockStack>
              </Card>

              {/* Reset app */}
              <Card>
                <BlockStack gap="200">
                  <Text as="p" variant="bodyMd" fontWeight="semibold">
                    Reset app data
                  </Text>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Delete widget configuration, recommender configuration, and all analytics events.
                    Size charts are not deleted.
                  </Text>
                  <InlineStack gap="200">
                    <Button
                      tone="critical"
                      onClick={() => {
                        setResetAppConfirm("");
                        setResetAppOpen(true);
                      }}
                    >
                      Reset app data
                    </Button>
                  </InlineStack>
                </BlockStack>
              </Card>
            </BlockStack>
          </BlockStack>
        </Card>

      </BlockStack>

      {/* ── Reset analytics modal ─────────────────────────────────────────── */}
      <Modal
        open={resetAnalyticsOpen}
        onClose={() => setResetAnalyticsOpen(false)}
        title="Clear all analytics data?"
        primaryAction={{
          content: "Clear analytics",
          destructive: true,
          onAction: () => submitIntent("reset-analytics"),
          loading: currentLoadingIntent === "reset-analytics",
        }}
        secondaryActions={[
          { content: "Cancel", onAction: () => setResetAnalyticsOpen(false) },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="300">
            <Text as="p" variant="bodyMd">
              This will permanently delete all analytics events including:
            </Text>
            <List gap="loose">
              <List.Item>Chart view events</List.Item>
              <List.Item>Size recommendation events</List.Item>
              <List.Item>Conversion and click events</List.Item>
            </List>
            <Banner tone="warning">
              <Text as="p" variant="bodyMd">
                This action cannot be undone. Export your data first if you need a record.
              </Text>
            </Banner>
          </BlockStack>
        </Modal.Section>
      </Modal>

      {/* ── Delete all charts modal ───────────────────────────────────────── */}
      <Modal
        open={deleteChartsOpen}
        onClose={() => setDeleteChartsOpen(false)}
        title={`Delete all ${chartCount} size chart${chartCount === 1 ? "" : "s"}?`}
        primaryAction={{
          content: "Delete all charts",
          destructive: true,
          onAction: () =>
            submitIntent("delete-all-charts", { confirmText: deleteChartsConfirm }),
          loading: currentLoadingIntent === "delete-all-charts",
          disabled: deleteChartsConfirm !== "DELETE",
        }}
        secondaryActions={[
          { content: "Cancel", onAction: () => setDeleteChartsOpen(false) },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            <Text as="p" variant="bodyMd">
              This will permanently delete all {chartCount} size chart
              {chartCount === 1 ? "" : "s"} and all product/collection assignments.
              This action cannot be undone.
            </Text>
            <Banner tone="critical">
              <Text as="p" variant="bodyMd">
                Charts will immediately stop showing on your storefront.
              </Text>
            </Banner>
            <TextField
              label='Type "DELETE" to confirm'
              value={deleteChartsConfirm}
              onChange={(value) => setDeleteChartsConfirm(value)}
              placeholder="DELETE"
              autoComplete="off"
              helpText="This field is case-sensitive."
            />
          </BlockStack>
        </Modal.Section>
      </Modal>

      {/* ── Reset app data modal ─────────────────────────────────────────── */}
      <Modal
        open={resetAppOpen}
        onClose={() => setResetAppOpen(false)}
        title="Reset app data?"
        primaryAction={{
          content: "Reset app data",
          destructive: true,
          onAction: () =>
            submitIntent("reset-app", { confirmText: resetAppConfirm }),
          loading: currentLoadingIntent === "reset-app",
          disabled: resetAppConfirm !== "DELETE",
        }}
        secondaryActions={[
          { content: "Cancel", onAction: () => setResetAppOpen(false) },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            <Text as="p" variant="bodyMd">
              This will permanently delete:
            </Text>
            <List gap="loose">
              <List.Item>Widget configuration and appearance settings</List.Item>
              <List.Item>AI recommender configuration and rules</List.Item>
              <List.Item>All analytics events</List.Item>
            </List>
            <Banner tone="warning">
              <Text as="p" variant="bodyMd">
                Your size charts and assignments are not affected.
              </Text>
            </Banner>
            <TextField
              label='Type "DELETE" to confirm'
              value={resetAppConfirm}
              onChange={(value) => setResetAppConfirm(value)}
              placeholder="DELETE"
              autoComplete="off"
              helpText="This field is case-sensitive."
            />
          </BlockStack>
        </Modal.Section>
      </Modal>

    </Page>
  );
}
